void set_original_addr(struct msghdr *m, struct tipc_msg *msg)
{
    struct sockaddr_tipc *dst = (struct sockaddr_tipc *)m->msg_name;

    if (!dst)
        return;

    dst->family = AF_TIPC;
    dst->addrtype = TIPC_ADDR_ID;
    memset(&dst->addr, 0, sizeof(dst->addr));

    dst->addr.id.ref = tipc_msg_orig_port(msg);
    dst->addr.id.node = tipc_msg_orig_node(msg);
    m->msg_namelen = sizeof(*dst);
}

void set_original_addr(struct msghdr *m, struct tipc_msg *msg)
{
    struct sockaddr_tipc *dst = (struct sockaddr_tipc *)m->msg_name;
    __u32 port = tipc_msg_orig_port(msg);
    __u32 node = tipc_msg_orig_node(msg);

    if (!dst)
        return;

    dst->family = AF_TIPC;
    dst->addrtype = TIPC_ADDR_ID;
    memset(&dst->addr.identity, 0, sizeof(dst->addr.identity));
    dst->addr.identity.port = port;
    dst->addr.identity.node = node;
    m->msg_namelen = sizeof(*dst);
}

