void tipc_set_origaddr(struct msghdr *m, struct tipc_msg *msg)
{
    struct sockaddr_tipc *st = (struct sockaddr_tipc *)m->msg_name;

    if (st) {
        st->family = AF_TIPC;
        st->addrtype = TIPC_ADDR_ID;
        memset(&st->addr, 0, sizeof(st->addr));
        st->addr.id.port = tipc_msg_hdr(msg)->source_ref;
        st->addr.id.node = tipc_msg_hdr(msg)->source_node;
        m->msg_namelen = sizeof(*st);
    }
}
